# --- dlc_gear_curation: opt-in item-pool gear curation (see options.py) -------
# Built once from the PvE tier data (ITEM_TIERS) joined with item_table's
# category / is_dlc fields.
#   CURATION_DROP_BASE_GEAR  = base-game (non-DLC) WEAPON/ARMOR rated C/D/F.
#       Dropped from the pool so their locations stay randomized checks but the
#       junk no longer spreads. Runs whenever the option is on (DLC or not).
#   CURATION_INJECT_DLC_GEAR = DLC WEAPON/ARMOR rated S/A. One extra copy each
#       backfills the freed slots -- only when Enable DLC is also on.
# Progression-classified gear is excluded from both (never drop/duplicate it).
_CURATION_GEAR_CATS = (ERItemCategory.WEAPON, ERItemCategory.ARMOR)
CURATION_DROP_BASE_GEAR = frozenset(
    _n for _n, _d in item_table.items()
    if _d.category in _CURATION_GEAR_CATS
    and not _d.is_dlc
    and _d.classification != ItemClassification.progression
    and ITEM_TIERS.get(_n) in ("C", "D", "F")
)
CURATION_INJECT_DLC_GEAR = tuple(
    _n for _n, _d in item_table.items()
    if _d.category in _CURATION_GEAR_CATS
    and _d.is_dlc
    and _d.classification != ItemClassification.progression
    and ITEM_TIERS.get(_n) in ("S", "A")
)

# --- spell curation: keep high-tier spells randomized in Trimmed (see options.py / 
# the location_pool 'trimmed' branch). HIGH_TIER_SPELLS = sorceries/incantations rated
# S or A in the PvE tier data. Spells are GOODS at the default 'filler' classification,
# so Trimmed drops them by default; this set lets the cream survive as checks. Gated to
# the spell er_code ranges so a same-named non-spell can never sneak in.
_SPELL_CODE_RANGES = ((4000, 8000), (2004000, 2008000))
def _is_spell_code(_code):
    return _code is not None and any(lo <= _code < hi for lo, hi in _SPELL_CODE_RANGES)
HIGH_TIER_SPELLS = frozenset(
    _n for _n, _d in item_table.items()
    if _d.category == ERItemCategory.GOODS
    and _is_spell_code(_d.er_code)
    and ITEM_TIERS.get(_n) in ("S", "A")
)
