# Main World
class EldenRing(World):
    """
    This is the description of the game that will be displayed on the AP website.
    """

    game = "EldenRing"
    options: EROptions
    options_dataclass = EROptions
    web = EldenRingWeb()
    settings: typing.ClassVar[EldenRingSettings]
    base_id = 69000
    required_client_version = (0, 6, 6)
    topology_present = True
    item_name_to_id = {data.name: data.ap_code for data in item_table.values() if data.ap_code is not None}
    location_name_to_id = {
        location.name: location.ap_code
        for locations in location_tables.values()
        for location in locations
        if location.ap_code is not None
    }
    location_name_groups = location_name_groups
    item_name_groups = item_name_groups
    location_descriptions = location_descriptions
    item_descriptions = item_descriptions
    
    all_excluded_locations: Set[str] = set()
    all_priority_locations: Set[str] = set()
    
    def visualize_world(self): # puml gets put in root folder
        Utils.visualize_regions(self.multiworld.get_region(self.multiworld.worlds[1].origin_region_name, 1), f"{self.multiworld.player_name[1]}.puml")

    def __init__(self, multiworld: MultiWorld, player: int):
        super().__init__(multiworld, player)
        self.local_itempool = None
        self.created_regions = None
        self.all_excluded_locations = set()
        self.all_priority_locations = set()
        self.explicit_indirect_conditions = False

    def generate_early(self) -> None:
        self.created_regions = set()
        # Alias: `limgrave_caves` is a documented synonym for `limgrave_underground`
        # (same 10 Limgrave underground dungeons). Only `limgrave_underground` is wired in
        # the entrance rules + _EXTRA_LOCK_KEYS lock map, so normalize the synonym here
        # before any region/lock logic reads extra_region_locks. Idempotent.
        if "limgrave_caves" in self.options.extra_region_locks.value:
            self.options.extra_region_locks.value.discard("limgrave_caves")
            self.options.extra_region_locks.value.add("limgrave_underground")
        # progressive_items (OptionSet) -> legacy boolean options. The consolidated
        # front-end is mapped onto the four booleans here (OR-union: set, never clear),
        # so all downstream logic + slot_data keep reading the booleans unchanged and a
        # legacy yaml that set a boolean directly still works. Empty set = no change.
        _pi = self.options.progressive_items.value
        if "stone_bells" in _pi:
            self.options.progressive_stone_bells.value = 1
        if "glovewort_bells" in _pi:
            self.options.progressive_glovewort_bells.value = 1
        if "flasks" in _pi:
            self.options.progressive_flasks.value = 1
        if "physick" in _pi:
            self.options.progressive_physick.value = 1
        self._inject_reserve_names = frozenset()
        # Region-count / Capital-goal spine (short Morgott runs). Default inert; populated below
        # when the option engages. Referenced by create_region / _is_location_available / the
        # lock-injection block, so initialise BEFORE any of those can run.
        self._spine_active = False
        self._spine_sealed_regions = set()
        self._spine_sealed_locks = set()
        # dlc_only_chain (SPEC-dlc-only-chain.md) state -- set in the messmer scope block.
        self._dlc_chain = False
        self._dlc_chain_order = []
        self._dlc_chain_managed_locks = set()
        self._spine_sealed_locations = set()
        self._spine_effective_count = 0
        # num_regions_chain (SPEC-num-regions-chain.md, Track A) -- inert unless engaged below.
        self._num_regions_chain = False
        self._num_regions_chain_order = []
        self._num_regions_chain_free_lock = None
        self._num_regions_chain_breadcrumb_locks = set()
        self._num_regions_chain_managed_locks = set()
        # DLC mini-campaign goal (Messmer): a short Land-of-Shadow run that keeps only the
        # front-half DLC and ends at Messmer. It is a DLC slice, so force dlc_only on (which in
        # turn forces enable_dlc + accessibility below). Force messmer_kindle off too -- the
        # Kindling shards gate Enir Ilim, which this goal seals, so they would be dead
        # progression. See region_spine.compute_dlc_mini_scope / SPEC-dlc-mini-campaign.md.
        if self.options.ending_condition.value == 5:  # option_messmer
            if not self.options.dlc_only:
                self.options.dlc_only.value = 1
                warning(f"{self.player_name}: ending_condition 'messmer' forces dlc_only on.")
            if self.options.messmer_kindle:
                self.options.messmer_kindle.value = 0
                warning(f"{self.player_name}: ending_condition 'messmer' seals Enir Ilim; "
                        f"forcing messmer_kindle off.")
        # Godrick mini-campaign (shortest base-game run, ends at Godrick the Grafted in
        # Stormveil). The goal boss is in the BASE game, so dlc_only (which strips all base
        # checks) is a contradiction -- force it off here, before the dlc_only forcing below.
        # If enable_dlc is on the DLC regions are simply sealed past the kept front (seal
        # block below). See region_spine.compute_godrick_scope.
        if self.options.ending_condition.value == 6:  # option_godrick
            if self.options.dlc_only:
                self.options.dlc_only.value = 0
                warning(f"{self.player_name}: ending_condition 'godrick' ends at a base-game "
                        f"boss; forcing dlc_only off.")
        import logging as _lg, os as _os
        _diag = ("ER-FUNDEMOTE-DIAG enter generate_early: accessibility.value=%r "
                 "option_minimal=%r gate=%r enable_dlc=%r location_pool=%r" % (
                 self.options.accessibility.value, self.options.accessibility.option_minimal,
                 self.options.accessibility.value == self.options.accessibility.option_minimal,
                 bool(self.options.enable_dlc), self.options.location_pool.value))
        _lg.error(_diag)
        try:
            with open(_os.path.join(_os.path.dirname(__file__), "ER_DIAG.txt"), "w") as _df:
                _df.write(_diag + "\n")
        except Exception:
            pass
        # dlc_only forces enable_dlc on: the DLC regions/maps/Enir-Ilim gate are all
        # gated on enable_dlc, and dlc_only must never run with DLC off.
        if self.options.dlc_only and not self.options.enable_dlc:
            self.options.enable_dlc.value = 1
            warning(f"{self.player_name}: dlc_only is set; forcing enable_dlc on.")
        # dlc_only forces early_leveling on: a DLC-only start never visits the base game where
        # Melina's grace trigger fires, so without it the player could never Level Up at a grace
        # (and the quick_start Lord's Runes would be unspendable). Setting the option here makes
        # the start-flag block below grant 4680 (Level Up) + 951 (suppress meeting) + co-grant
        # Torrent, and the diag reflects Early Leveling = Yes.
        if self.options.dlc_only and not self.options.early_leveling:
            self.options.early_leveling.value = 1
            warning(f"{self.player_name}: dlc_only is set; forcing early_leveling on (no Melina meeting in a DLC-only start).")
        # dlc_only also forces two settings the mode needs to generate (previously set by
        # hand in the yaml): accessibility=minimal -- base regions are kept as locked-vanilla
        # transit so "full" would demand every base location be individually reachable -- and
        # important_locations=[] -- the DLC-only priority-fill phase has too few in-scope
        # priority locations to satisfy a non-empty priority set.
        if self.options.dlc_only:
            if self.options.accessibility.value != self.options.accessibility.option_minimal:
                self.options.accessibility.value = self.options.accessibility.option_minimal
                warning(f"{self.player_name}: dlc_only is set; forcing accessibility to minimal.")
            if self.options.important_locations.value:
                self.options.important_locations.value = []
                warning(f"{self.player_name}: dlc_only is set; clearing important_locations.")
        self.all_excluded_locations.update(self.options.exclude_locations.value)
        # self.all_priority_locations.update(self.options.priority_locations.value)

        # Important locations -> AP PRIORITY (forced to hold a progression item). A location
        # qualifies if ANY selected class matches it. (Previously a stray `break` inside the
        # per-class loop exited after the FIRST selected class, so e.g. the default
        # ["Remembrance","Seedtree","Map"] only ever applied "Remembrance".)
        dlc = bool(self.options.enable_dlc)
        priority_class_predicates = {
            "remembrance": lambda loc: loc.remembrance,
            "seedtree":    lambda loc: loc.seedtree,
            "basin":       lambda loc: loc.basin,
            "church":      lambda loc: loc.church,
            "map":         lambda loc: loc.map,
            "fragment":    lambda loc: loc.fragment and dlc,
            "cross":       lambda loc: loc.cross and dlc,
            "revered":     lambda loc: loc.revered and dlc,
            "keyitem":     lambda loc: loc.keyitem,
            "boss":        lambda loc: loc.boss,
            "shop":        lambda loc: loc.shop and not loc.missable and "twin maiden" in loc.name.lower(),
        }
        selected_priority_classes = [
            c for c in (t.lower() for t in self.options.important_locations.value)
            if c in priority_class_predicates
        ]
        # flask_upgrade_option / blessing_option were merged away: their "to important" behavior is
        # now just listing Seedtree/Church/Fragment/Revered in important_locations (the default
        # includes all four). "do not randomize" -> vanilla_upgrades (below + in _fill_local_items).
        # --- num_regions / Enia-aware priority selection (patch_apworld_important_locations_scope) ---
        # A Remembrance item only gates the Enia turn-in checks, so it is real progression ONLY
        # when randomize_enia is on. With Enia vanilla it buys optional gear 1:1 and gates nothing
        # -> never promote its drop-location to PRIORITY (it would crowd the constrained fill).
        if not self.options.randomize_enia:
            selected_priority_classes = [c for c in selected_priority_classes if c != "remembrance"]
        # (1) IN-SCOPE filter: only randomized, in-pool, non-excluded locations are PRIORITY-eligible.
        #     Sealed (num_regions / spine) regions and vanilla Enia slots fail _is_location_available.
        # (2) HEADROOM cap (spine seals only): keep >= _PRIO_HEADROOM free randomizable slots per
        #     region so the lock chain + injected runes always have a reachable home (else the
        #     priority pass eats the scarce kept slots -> 'No more spots to place N items.').
        _spine_seal = bool(getattr(self, "_spine_active", False))
        _PRIO_HEADROOM = 2
        for _region_name, _region_locs in location_tables.items():
            _avail = [l for l in _region_locs
                      if self._is_location_available(l) and l.name not in self.all_excluded_locations]
            _cand = [l for l in _avail
                     if any(priority_class_predicates[c](l) for c in selected_priority_classes)]
            if _spine_seal and _cand:
                _allowed = max(0, len(_avail) - _PRIO_HEADROOM)
                if len(_cand) > _allowed:
                    _cand = sorted(_cand, key=lambda l: l.name)[:_allowed]
            for l in _cand:
                self.all_priority_locations.update({l.name})
        # do_not_randomize categories are vanilla-locked, so they must NOT also be priority
        # (overrides important_locations / the above for the affected classes).
        _vu = self.options.vanilla_upgrades.value
        if ("flasks" in _vu) or ("blessings" in _vu and dlc):
            for locations in location_tables.values():
                for loc in locations:
                    if "flasks" in _vu and (loc.seedtree or loc.church):
                        self.all_priority_locations.discard(loc.name)
                    if "blessings" in _vu and dlc and (loc.fragment or loc.revered):
                        self.all_priority_locations.discard(loc.name)

        # Remembrance items gate only the Enia turn-in checks (see priority block above). With
        # randomize_enia OFF they gate nothing required -> demote them out of progression so they
        # stop crowding the constrained (region_lock / num_regions) progression+priority fill.
        # Added to _fun_demoted so the gate-shorthand asserts stay relaxed. Reachability goals
        # (ending_condition==2) use the LOCATIONS not the items, so this is goal-safe.
        # (patch_apworld_important_locations_scope)
        if not self.options.randomize_enia:
            self._fun_demoted = getattr(self, "_fun_demoted", set())
            _rem_demoted = 0
            for _tbl in (item_table, item_table_vanilla):
                for _data in _tbl.values():
                    if (_data.classification == ItemClassification.progression
                            and _data.name.startswith("Remembrance")):
                        _data.classification = ItemClassification.useful
                        _data.filler = False
                        self._fun_demoted.add(_data.name)
                        _rem_demoted += 1
        
        if self.settings.disable_extreme_options:
            if not self.options.local_item_option:
                raise OptionError(f"EldenRing disable_extreme_options Error:"
                                  f"Player {self.player_name} has local_item_option false."
                                  f"This being false means over 3.5k checks come from this world.")
            elif "goods" in [key.lower() for key in self.options.exclude_local_item_only.value]:
                raise OptionError(f"EldenRing disable_extreme_options Error:"
                                  f"Player {self.player_name} has goods enabled in exclude_local_item_only."
                                  f"This being here means over 3.5k checks come from this world and it bypasses local_item_option.")
            elif self.options.ending_condition == 3:
                raise OptionError(f"EldenRing disable_extreme_options Error:"
                                  f"Player {self.player_name} has ending_condition set to all bosses.")      
     
        if self.options.smithing_bell_bearing_option.value == 1:
            item_table["Smithing-Stone Miner's Bell Bearing [1]"].classification = ItemClassification.progression
            item_table["Smithing-Stone Miner's Bell Bearing [2]"].classification = ItemClassification.progression
            item_table["Smithing-Stone Miner's Bell Bearing [3]"].classification = ItemClassification.progression
            item_table["Smithing-Stone Miner's Bell Bearing [4]"].classification = ItemClassification.progression
            item_table["Somberstone Miner's Bell Bearing [1]"].classification = ItemClassification.progression
            item_table["Somberstone Miner's Bell Bearing [2]"].classification = ItemClassification.progression
            item_table["Somberstone Miner's Bell Bearing [3]"].classification = ItemClassification.progression
            item_table["Somberstone Miner's Bell Bearing [4]"].classification = ItemClassification.progression
            item_table["Somberstone Miner's Bell Bearing [5]"].classification = ItemClassification.progression

        # Merchant bell-bearing logic (logic-only): promote each gated merchant's Bell
        # Bearing to an in-pool progression item so its shop checks can require it.
        # NOTE mutates the module-level item_table (same pattern as the smithing block
        # above). Only bells with a real world drop are listed (see merchant_bells.py).
        # [shop-checks] only force the bells to progression when shop checks exist; with shops
        # excluded (shop_checks off) the gated shop checks vanish, so forcing the bells would
        # gate nothing. Demote them to normal items in that case. See SPEC-shop-checks.md.
        if self.options.merchant_bell_logic.value == 1 and self.options.shop_checks.value:
            for _bell in merchant_bell_names(bool(self.options.enable_dlc)):
                item_table[_bell].skip = False
                item_table[_bell].classification = ItemClassification.progression

        # Soft progression (wiggle room): under strict accessibility (full/items), demote boring
        # progression that gates NOTHING in logic -- upgrade Bell Bearings + Progressive Flask of
        # Wondrous Physick -- to useful, so meaningful progression lands on important_locations
        # under full without being diluted. (Smithing stones are already filler.) See SPEC.
        if self.options.soft_progression.value:
            for _sp in item_table.values():
                if _sp.classification == ItemClassification.progression and (
                        "Bell Bearing" in _sp.name or "Flask of Wondrous Physick" in _sp.name):
                    _sp.classification = ItemClassification.useful

        # Tidy junk 'fun consumables': pull from the pool (progression-classed, gate ~nothing).
        # Festering Bloody Fingers gate nothing; Starlight Shards / Seedbed Curses are start-
        # granted at their required counts in _fill_local_items so the gated checks stay reachable.
        if self.options.tidy_fun_consumables.value:
            for _vn in ("Festering Bloody Finger", "Festering Bloody Finger x2",
                        "Festering Bloody Finger x3", "Festering Bloody Finger x5",
                        "Festering Bloody Finger x6", "Festering Bloody Finger x8",
                        "Festering Bloody Finger x10", "Starlight Shards", "Seedbed Curse", "Shabriri Grape"):
                if _vn in item_table: item_table[_vn].skip = True

        # progressive_physick: the ladder's step 1 grants the flask, so drop the redundant base
        # "Flask of Wondrous Physick" from the pool (was double-counted). (unplaced-audit 2026-06-19.)
        if self._progressive_physick_active() and "Flask of Wondrous Physick" in item_table:
            item_table["Flask of Wondrous Physick"].skip = True

        # Soft-consumable shop / Gurranq de-rando: pull these from the randomized pool BEFORE
        # create_items builds it. Keys/hearts become Twin Maiden shop stock; Deathroot is locked
        # vanilla at the Gurranq ladder (see _fill_local_items). SPEC-soft-consumables.md.
        if self.options.key_gates_missable.value:
            # [key-gates] pure-runtime replacement for the soft-shop key handling: Stonesword Keys,
            # Dragon Hearts and Imbued Sword Keys become ordinary FILLER (their imp-seal / Dragon
            # Communion / Four Belfries locations are flagged EXCLUDED in set_rules), so they no longer
            # drag into the progression/priority fill. No baked Twin Maiden shop rows needed.
            for _vn in ("Stonesword Key", "Stonesword Key x3", "Stonesword Key x5",
                        "Dragon Heart", "Dragon Heart x3", "Dragon Heart x5", "Imbued Sword Key"):
                if _vn in item_table:
                    item_table[_vn].classification = ItemClassification.filler
        elif self.options.soft_consumable_shop.value:
            for _vn in ("Stonesword Key", "Stonesword Key x3", "Stonesword Key x5"):
                if _vn in item_table: item_table[_vn].skip = True
            if not self.options.dlc_only:  # dlc_only precollects its own 25 hearts
                for _vn in ("Dragon Heart", "Dragon Heart x3", "Dragon Heart x5"):
                    if _vn in item_table: item_table[_vn].skip = True
            if "Imbued Sword Key" in item_table:  # Twin Maiden Husks sells it infinitely
                item_table["Imbued Sword Key"].skip = True
        if self.options.derandomize_gurranq.value:
            if "Deathroot" in item_table: item_table["Deathroot"].skip = True
        
        # Region-count / Capital spine (short Morgott runs). Resolve scope BEFORE the lock
        # injection below so sealed locks can be pulled from the pool. Only engages with the
        # Capital goal AND a lock-based world logic (region_lock / region_lock_bosses) -- with any
        # other goal the goal boss lives past the sealed wall, and without locks there is nothing
        # to seal. See region_spine.py / SPEC-region-count-morgott.md.
        # region_count was MERGED into num_regions (num_regions_order: spine; pre-1.0 hard removal).
        # The fixed first-N spine path now runs in the num_regions branch below, dispatched on
        # num_regions_order and still calling region_spine.compute_region_scope.

        # DLC mini-campaign (Messmer goal): seal every DLC region past the kept front-half so
        # the run ends at Messmer. Reuses the same _spine_* seal fields as the Capital spine
        # (sealed locks pulled from the pool below; sealed-region checks -> locked-vanilla
        # events in create_region). DLC-scoped only -- base regions/locks stay as dlc_only
        # transit. See region_spine.compute_dlc_mini_scope.
        if self.options.ending_condition.value == 5:  # option_messmer
            if self.options.world_logic.value not in (0, 2):
                warning(f"{self.player_name}: ending_condition 'messmer' needs world_logic "
                        f"region_lock / region_lock_bosses to seal the DLC; running the full "
                        f"DLC pool instead.")
            else:
                _dlc_regions = set(region_order_dlc)
                _all_locks = {n for n, d in item_table.items() if getattr(d, "lock", False)}
                _dlc_locks = {n for n, d in item_table.items()
                              if getattr(d, "lock", False) and getattr(d, "is_dlc", False)}
                _kept_r, _sealed_r, _kept_l, _sealed_l = region_spine.compute_dlc_mini_scope(
                    _dlc_regions, _all_locks, _dlc_locks,
                )
                self._spine_active = True
                self._spine_sealed_regions = _sealed_r
                self._spine_sealed_locks = _sealed_l
                self._spine_sealed_locations = {
                    loc.name for r in _sealed_r for loc in location_tables.get(r, [])
                }
                # dlc_only_chain (SPEC-dlc-only-chain.md, Phase 1 / Option A): breadcrumb the
                # messmer kept-set DLC locks into a linear chain off the free Gravesite hub. We
                # only record the ORDER + managed-lock set here; placement happens in pre_fill
                # (needs created locations) and the inject=False de-pooling happens in the dlc_only
                # lock block below. No-op unless dlc_only_chain is on.
                if getattr(self.options, "dlc_only_chain", None) and self.options.dlc_only_chain.value:
                    self._dlc_chain = True
                    self._dlc_chain_order = region_spine.compute_dlc_mini_chain_order(
                        self.random, set(_kept_l))
                    self._dlc_chain_managed_locks = set(self._dlc_chain_order)

        # Godrick mini-campaign: seal the rest of the base game (and all DLC) past the kept
        # front three steps (Limgrave / Weeping / Stormveil) so the run ends at Godrick. Same
        # _spine_* seal path as the Capital spine and the Messmer mini-campaign; needs a
        # lock-based world logic to seal (dlc_only already forced off above). See
        # region_spine.compute_godrick_scope.
        if self.options.ending_condition.value == 6:  # option_godrick
            if self.options.world_logic.value not in (0, 2):
                warning(f"{self.player_name}: ending_condition 'godrick' needs world_logic "
                        f"region_lock / region_lock_bosses to seal the world; running the full "
                        f"pool instead.")
            else:
                _all_regions = set(region_order)
                if self.options.enable_dlc:
                    _all_regions |= set(region_order_dlc)
                _all_locks = {n for n, d in item_table.items() if getattr(d, "lock", False)}
                _kept_r, _sealed_r, _kept_l, _sealed_l = region_spine.compute_godrick_scope(
                    _all_regions, _all_locks,
                )
                self._spine_active = True
                self._spine_sealed_regions = _sealed_r
                self._spine_sealed_locks = _sealed_l
                self._spine_sealed_locations = {
                    loc.name for r in _sealed_r for loc in location_tables.get(r, [])
                }

        # num_regions (SPEC-num-regions.md): a RANDOM short capital run -- keep `num_regions`
        # overworld majors chosen at random (Limgrave hub + Leyndell/Morgott capstone always in,
        # the middle majors rolled with a great-rune floor) and seal the rest. Same _spine_* seal
        # path as region_count; capital goal + lock logic only; forces region_access=warp so the
        # non-contiguous random subset is reachable from the Limgrave hub by each region's lock.
        if self.options.num_regions.value > 0:
            if self.options.ending_condition.value != 4:  # option_capital
                warning(f"{self.player_name}: num_regions needs ending_condition 'capital' "
                        f"(the goal boss must sit inside the kept set); ignoring num_regions.")
            elif self.options.world_logic.value not in (0, 2):
                warning(f"{self.player_name}: num_regions needs world_logic region_lock / "
                        f"region_lock_bosses (it seals regions via their lock items); ignoring it.")
            elif getattr(self, "_spine_active", False):
                warning(f"{self.player_name}: num_regions overlaps another region-seal goal "
                        f"(messmer/godrick); ignoring num_regions.")
            else:
                _all_regions = set(region_order)
                if self.options.enable_dlc:
                    _all_regions |= set(region_order_dlc)
                _all_locks = {n for n, d in item_table.items() if getattr(d, "lock", False)}
                _active_caves = region_spine.active_cave_steps(self.options.extra_region_locks.value)
                _spine_order = self.options.num_regions_order.value == 1  # option_spine (was region_count)
                try:
                    if _spine_order:
                        # spine: fixed first-N steps toward Morgott, reached geographically (the old
                        # region_count). No random roll, no cave-bundle split, no forced warp.
                        _kept_r, _sealed_r, _kept_l, _sealed_l, _eff = region_spine.compute_region_scope(
                            self.options.num_regions.value,
                            self.options.great_runes_required.value,
                            _all_regions, _all_locks,
                        )
                    else:
                        # random: roll N majors; reached by warp (forced below).
                        _kept_r, _sealed_r, _kept_l, _sealed_l, _eff = region_spine.compute_num_regions_scope(
                            self.random,
                            self.options.num_regions.value,
                            self.options.great_runes_required.value,
                            _all_regions, _all_locks,
                            _active_caves,
                        )
                except ValueError as _e:
                    raise OptionError(f"{self.player_name}: {_e}")
                self._spine_active = True
                self._spine_sealed_regions = _sealed_r
                self._spine_sealed_locks = _sealed_l
                self._spine_effective_count = _eff
                self._spine_sealed_locations = {
                    loc.name for r in _sealed_r for loc in location_tables.get(r, [])
                }
                if not _spine_order and self.options.region_access.value != 1:
                    self.options.region_access.value = 1
                    warning(f"{self.player_name}: num_regions (random order) forces region_access=warp "
                            f"(a random non-contiguous region set needs warp reachability).")
                if _eff != self.options.num_regions.value:
                    warning(f"{self.player_name}: num_regions {self.options.num_regions.value} "
                            f"raised to {_eff} so the capital (Morgott) stays reachable.")

                # num_regions_rune_source == pool (SPEC-num-regions-pool-runes.md): decouple the
                # great-rune floor from region selection. Re-run the scope with the POOL sibling
                # (no rune floor, no Altus force, Limgrave rollable), then inject the deficit great
                # runes back into the item pool so Leyndell's pure item-count gate is still met. The
                # Roundtable-hub re-root (set after the _random_start_region reset below) makes the
                # non-contiguous random set reachable by warp.
                _pool_runes = self.options.num_regions_rune_source.value == 1  # option_pool
                if _pool_runes and _spine_order:
                    warning(f"{self.player_name}: num_regions_rune_source=pool is ignored under "
                            f"num_regions_order=spine (pool rolls a random non-contiguous set).")
                    _pool_runes = False
                if _pool_runes:
                    _kept_r, _sealed_r, _kept_l, _sealed_l, _eff = \
                        region_spine.compute_num_regions_scope_pool(
                            self.random,
                            self.options.num_regions.value,
                            _all_regions, _all_locks,
                            _active_caves,
                            bool(self.options.num_regions_chain.value),
                        )
                    self._spine_sealed_regions = _sealed_r
                    self._spine_sealed_locks = _sealed_l
                    self._spine_effective_count = _eff
                    self._spine_sealed_locations = {
                        loc.name for r in _sealed_r for loc in location_tables.get(r, [])
                    }
                    # Roundtable-hub re-root: arm the flag the existing random_start path keys on.
                    # Actually set self._random_start_region AFTER the unconditional reset below
                    # (it would otherwise be clobbered); record intent here.
                    self._num_regions_pool_reroot = True
                    # Inject the DEFICIT great runes (great_runes_required minus the rune bosses
                    # still in a KEPT region) into the pool. _kept_l holds the kept locks; a rune's
                    # step is kept iff its lock is kept. Candidates = the 4 base-spine runes in a
                    # SEALED step; Morgott's is excluded (goal-side). Flipping inject=True routes
                    # each rune through the create_items demand-drop -> a freed filler slot per
                    # rune keeps the pool count-neutral. Dedup so a rune is never injected twice.
                    _step_lock = region_spine.NUM_REGIONS_CHAIN_STEP_LOCK
                    _step_rune = region_spine.NUM_REGIONS_STEP_GREAT_RUNE
                    _kept_rune_steps = [s for s in _step_rune
                                        if _step_lock.get(s) in _kept_l]
                    # great_runes_present was removed (Part 2): the deficit injection now always
                    # targets exactly great_runes_required.
                    _gr_target = int(self.options.great_runes_required.value)
                    _need = max(0, _gr_target - len(_kept_rune_steps))
                    _sealed_rune_steps = [s for s in sorted(_step_rune)
                                          if s not in _kept_rune_steps]
                    _inject_runes = []
                    for _s in _sealed_rune_steps:
                        if len(_inject_runes) >= _need:
                            break
                        _rn = _step_rune[_s]
                        if _rn in item_table and _rn not in _inject_runes:
                            _inject_runes.append(_rn)
                    for _rn in _inject_runes:
                        item_table[_rn].inject = True
                    self._num_regions_pool_injected_runes = list(_inject_runes)
                    if _need > len(_inject_runes):
                        warning(f"{self.player_name}: num_regions pool rune-source could only "
                                f"source {len(_inject_runes)} of {_need} great runes from sealed "
                                f"base bosses; check great_runes_required vs available runes.")
                    warning(f"{self.player_name}: num_regions rune-source=pool -- kept {_eff} "
                            f"middle region(s), injecting great runes {sorted(_inject_runes)} "
                            f"into the pool (Roundtable hub, Limgrave rollable).")

                # num_regions_chain (SPEC-num-regions-chain.md, Track A): force the kept middles
                # into a linear lock-breadcrumb chain so the fill spheres ramp 1..N. We only record
                # the ORDER + the chain locks here; the actual placement happens in pre_fill (after
                # locations exist) and the inject=False de-pooling happens in the lock-injection
                # block below. _spine_active is already True (this is inside the num_regions branch).
                self._num_regions_chain = bool(self.options.num_regions_chain.value)
                if self._num_regions_chain:
                    _chain_order = region_spine.compute_num_regions_chain_order(self.random, _kept_l)
                    self._num_regions_chain_order = _chain_order
                    # The chain locks = every kept middle's chain lock. The FIRST link's lock is
                    # free (precollected); the rest are breadcrumbed onto the prior link's boss.
                    _chain_locks = [region_spine.NUM_REGIONS_CHAIN_STEP_LOCK[s] for s in _chain_order]
                    self._num_regions_chain_free_lock = _chain_locks[0] if _chain_locks else None
                    self._num_regions_chain_breadcrumb_locks = set(_chain_locks[1:])
                    # Breadcrumb host map filled in pre_fill (needs created locations); for the
                    # inject pass we only need the set of locks that LEAVE the random pool.
                    self._num_regions_chain_managed_locks = set(_chain_locks)
                    if 6 in _chain_order and 5 not in _chain_order:
                        warning(f"{self.player_name}: num_regions_chain kept Dragonbarrow without "
                                f"Caelid; Dragonbarrow has no hub warp, so it may be unreachable "
                                f"under warp access -- gen-test this seed (SPEC-num-regions-chain  9).")

        # Dead/redundant vanilla key items -> free great runes (num_regions). Collect keys that gate
        # only sealed (or warp-redundant) regions, and the runes free to give (boss region/step sealed
        # -> not already in the pool; same kept/sealed test as the deficit-injector, so a swap can
        # never duplicate a pool rune). create_items pops one rune per IN-POOL dead key; leftovers ->
        # filler. Count-neutral; each dead key's location stays a check. No-op when a region is kept.
        self._deadkey_swap_set = frozenset()
        self._deadkey_rune_queue = []
        if self.options.num_regions.value > 0 and getattr(self, "_spine_active", False):
            _sealed_rr = getattr(self, "_spine_sealed_regions", set())
            _sealed_lk = getattr(self, "_spine_sealed_locks", set())
            _injected = getattr(self, "_num_regions_pool_injected_runes", [])
            _dead = []
            if "Mountaintops of the Giants" in _sealed_rr and "Consecrated Snowfield" in _sealed_rr:
                _dead.append("Rold Medallion")
            if "Elphael, Brace of the Haligtree" in _sealed_rr:
                _dead += ["Haligtree Secret Medallion (Left)", "Haligtree Secret Medallion (Right)"]
            if self.options.region_access == "warp":
                _dead += ["Dectus Medallion (Left)", "Dectus Medallion (Right)"]
            self._deadkey_swap_set = frozenset(k for k in _dead if k in item_table)
            _free = []
            for _r, _reg in (("Mohg's Great Rune", "Mohgwyn Palace"),
                             ("Malenia's Great Rune", "Elphael, Brace of the Haligtree")):
                if _reg in _sealed_rr and _r in item_table and _r not in _injected:
                    _free.append(_r)
            _step_lock = region_spine.NUM_REGIONS_CHAIN_STEP_LOCK
            for _s, _r in sorted(region_spine.NUM_REGIONS_STEP_GREAT_RUNE.items()):
                if (_step_lock.get(_s) in _sealed_lk and _r in item_table
                        and _r not in _injected and _r not in _free):
                    _free.append(_r)
            self._deadkey_rune_queue = _free
            # patch_apworld_numregions_dead_progression (A): _free are SURPLUS sealed-region
            # great runes (NOT the gate-counting set -- that is _inject_runes + kept-step runes).
            # They only enter the pool via the dead-key swap in create_items, which does
            # create_item(rune) at the rune's DEFAULT classification == progression -> each then
            # demands a reachable kept home and overflows the tiny kept fill. Demote them to useful
            # so the swap creates them as useful (still placed at the dead-key location,
            # count-neutral, but out of the progression/priority fill). Gate stays satisfiable.
            for _drn in _free:
                if _drn in item_table and item_table[_drn].classification == ItemClassification.progression:
                    item_table[_drn].classification = ItemClassification.useful
                    item_table[_drn].filler = False
        # Accessibility-aware dead-access skip (patch numregions_survival_floor / dead_access):
        # drop region-access items whose gated content is unreachable this seed so they stop
        # occupying pool slots. Pureblood Knight's Medal is progression ONLY under enable_dlc
        # (entrance rules all DLC-gated); with DLC off it is a plain warp medal -> skip it. Imbued
        # Sword Key gates only the Four Belfries waygates; skip when every destination is sealed.
        _sealed_rr2 = getattr(self, "_spine_sealed_regions", set())
        if "Pureblood Knight's Medal" in item_table and not self.options.enable_dlc:
            item_table["Pureblood Knight's Medal"].skip = True
        if self.options.enable_dlc and "Imbued Sword Key" in item_table:
            _belfry_targets = {"The Four Belfries (Chapel of Anticipation)",
                               "The Four Belfries (Nokron)", "The Four Belfries (Farum Azula)",
                               "Ancient Ruins of Rauh"}
            if _belfry_targets <= _sealed_rr2:
                item_table["Imbued Sword Key"].skip = True
        if self.options.world_logic == "region_lock" or self.options.world_logic == "region_lock_bosses": # inject keys
            for item in item_table:
                if item_table[item].lock:
                    item_table[item].inject = True
            # Godrick-only granularity locks: inject ONLY under the Godrick goal, else they
            # would add progression items that gate nothing to normal region_lock seeds.
            _EXTRA_LOCK_KEYS = {"Stormhill Lock": "stormhill", "Godrick Lock": "godrick", "Morne Lock": "castle_morne", "Spelunker's Messmerflame Torch": "dlc_catacombs"}
            _EXTRA_LOCK_KEYS["Spelunker's Steel-Wire Torch"] = "altus_caves"  # opt-in Altus minor-dungeon bundle
            _EXTRA_LOCK_KEYS["Spelunker's Beast-Repellent Torch"] = "mountaintops_caves"  # opt-in Mountaintops bundle
            _EXTRA_LOCK_KEYS["Spelunker's Torch"] = "limgrave_underground"  # opt-in Limgrave underground bundle
            _EXTRA_LOCK_KEYS["Spelunker's Ghostflame Torch"] = "liurnia_caves"  # opt-in Liurnia minor-dungeon bundle
            _EXTRA_LOCK_KEYS["Snowfield Lock"] = "snowfield"  # opt-in: split Consecrated Snowfield off (dedicated lock)
            for _lk, _key in _EXTRA_LOCK_KEYS.items():
                if _lk in item_table and _key not in self.options.extra_region_locks.value:
                    item_table[_lk].inject = False
            # Haligtree natural-key conversion (medallion split): Haligtree Lock is no longer a
            # pool item -- Miquella's Haligtree is gated by the Right Haligtree Secret Medallion
            # (vanilla key) and bloomed client-side via naturalKeyTriggers. De-inject always.
            if "Haligtree Lock" in item_table:
                item_table["Haligtree Lock"].inject = False
            # Region-count spine: seal regions past the count by pulling their lock items from the
            # pool (unobtainable -> the gated entrance can never open). Kept-step locks stay injected.
            if self._spine_active:
                for _lk in self._spine_sealed_locks:
                    if _lk in item_table:
                        item_table[_lk].inject = False
            # num_regions_chain (Track A): the breadcrumbed + precollected chain locks are
            # placed by hand (pre_fill / push_precollected), so pull them from the RANDOM injectable
            # pool -- otherwise they would be randomly placed (or spilled to start) on TOP of the
            # fixed placement. create_items keeps the pool count-neutral (the freed slot -> filler).
            if getattr(self, "_num_regions_chain", False):
                for _lk in getattr(self, "_num_regions_chain_managed_locks", ()):  # free + breadcrumb
                    if _lk in item_table:
                        item_table[_lk].inject = False
            # num_regions / spine seal: the smithing-bell entrance gate (Altus / Capital Outskirts /
            # Flame Peak / Farum requiring Miner's Bell Bearings) is fabricated -- vanilla ER never
            # gates area access on bell bearings -- and in a tiny sealed pool it force-places ~15
            # progressive bells (+ progressive physick) as PROGRESSION, overflowing the fill
            # ("No more spots to place ..."). For spine-seal seeds turn the smithing-bell option OFF
            # (entrance rules won't fire) and demote the bells + Wondrous Physick back to useful.
            # (patch_apworld_spine_seal_bell_relief.py)
            if getattr(self, "_spine_active", False):
                if self.options.smithing_bell_bearing_option.value == 1:
                    self.options.smithing_bell_bearing_option.value = 0
                # accessibility floor (patch numregions_survival_floor): demoting ALL bells +
                # Flask of Wondrous Physick to useful left them with NO reachability guarantee, so
                # in a tiny sealed pool they strand in other worlds / sealed regions (observed sync
                # 2026-06-20: whole run with zero flask upgrades + zero smithing bells). Keep a small
                # FLOOR reachable as progression_skip_balancing (logic-placed, but skipped by the
                # cross-player balancing pass so the tiny pool does not overflow); demote the rest.
                _survival_floor = {
                    "Smithing-Stone Miner's Bell Bearing [1]",
                    "Smithing-Stone Miner's Bell Bearing [2]",
                    "Somberstone Miner's Bell Bearing [1]",
                    "Flask of Wondrous Physick",
                }
                for _rn in list(item_table):
                    if ("Miner's Bell Bearing" in _rn) or ("Flask of Wondrous Physick" in _rn):
                        if _rn in _survival_floor:
                            item_table[_rn].classification = ItemClassification.progression_skip_balancing
                            item_table[_rn].filler = False
                        else:
                            item_table[_rn].classification = ItemClassification.useful
            # dlc_only + region_lock: Gravesite Plain is the DLC's free hub (you START there --
            # it's the "Limgrave" of the DLC), so precollect ONLY its lock and leave every other
            # region lock in the pool, gated by region_lock. The DLC region graph is a connected
            # tree rooted at Gravesite (Gravesite -> Belurat/Ellac/Jagged Peak/Ensis -> Scadu
            # Altus -> Shadow Keep -> Ancient Ruins -> Enir Ilim), so the fill bootstraps from
            # Gravesite's checks and cascades. Messmer's Kindling on Enir Ilim stays the real spine
            # (shards still distributed in the DLC pool). Base prereqs precollected below.
            # NOTE: pre-region-lock behaviour granted EVERY lock (free-entry); that disabled
            # region_lock in dlc_only. Set _DLC_ONLY_FREE_ALL_LOCKS=True to restore it.
            _DLC_ONLY_FREE_ALL_LOCKS = False
            if self.options.dlc_only:
                for item in item_table:
                    if not item_table[item].lock:
                        continue
                    if _DLC_ONLY_FREE_ALL_LOCKS or item == "Gravesite Lock":
                        item_table[item].inject = False
                        self.multiworld.push_precollected(self.create_item(item))
                    elif not getattr(item_table[item], "is_dlc", False):
                        # dlc_only: pull BASE-game region locks from the pool (sealed
                        # transit, no findable lock); DLC locks (is_dlc) stay injected.
                        # Count-neutral -- see the L1418 demand-drop comment.
                        item_table[item].inject = False
                # dlc_only_chain (SPEC-dlc-only-chain.md): the chained kept DLC locks are placed by
                # hand on boss drops in pre_fill, so pull them from the RANDOM injectable pool here
                # (else they'd be randomly placed on top of the fixed breadcrumb). Gravesite is
                # already precollected above. Count-neutral (freed slot -> filler in create_items).
                if getattr(self, "_dlc_chain", False):
                    for _clk in getattr(self, "_dlc_chain_managed_locks", ()):
                        if _clk in item_table:
                            item_table[_clk].inject = False
                # dlc_only: a DLC-only player has already cleared the base game, so DLC
                # content that gates on BASE progression items would otherwise be
                # permanently unreachable -- those items are not in the DLC-only pool.
                # Precollect the base prerequisites: great runes (Enia Roundtable
                # remembrance trades via _has_enough_great_runes), the Crafting Kit
                # (furnace-golem pot crafting), and Dragon Hearts (Jagged Peak Grand
                # Dragon Communion needs 23 via _has_enough_hearts).
                _dlc_only_base_prereqs = [
                    "Godrick's Great Rune", "Rykard's Great Rune", "Radahn's Great Rune",
                    "Morgott's Great Rune", "Mohg's Great Rune", "Malenia's Great Rune",
                    "Great Rune of the Unborn",
                    "Crafting Kit",
                ]
                for _pre in _dlc_only_base_prereqs:
                    self.multiworld.push_precollected(self.create_item(_pre))
                # 5x "Dragon Heart x5" = 25 hearts (>= the 23 the Communion requires).
                for _ in range(5):
                    self.multiworld.push_precollected(self.create_item("Dragon Heart x5"))
                # Fix B (demand-restore): keep a sized set of the cheapest cut DLC filler
                # locations as checks so create_items has freed slots to seat the DLC region
                # locks + Messmer shards IN-WORLD instead of spilling them to the start
                # inventory (which silently disables region_lock + the Enir Ilim gate). Only
                # as many as the DLC mandatory-injectable demand; leftover reserve slots just
                # hold filler. Selected in DLC region order so early-sphere slots exist.
                if self.options.location_pool.value in (1, 2):
                    _dlc_lock_demand = sum(
                        1 for _n, _d in item_table.items()
                        if getattr(_d, "lock", False) and getattr(_d, "is_dlc", False)
                        and getattr(_d, "inject", False))
                    _shard_demand = (self.options.messmer_kindle_max.value
                                     if self.options.messmer_kindle else 1)
                    _reserve_target = _dlc_lock_demand + _shard_demand
                    _reserve = []
                    for _rn in list(region_order_dlc):
                        if len(_reserve) >= _reserve_target:
                            break
                        for _ld in location_tables.get(_rn, []):
                            if len(_reserve) >= _reserve_target:
                                break
                            if not self._content_in_scope(_ld):
                                continue
                            if getattr(_ld, "missable", False):
                                continue
                            if _ld.name in self.all_excluded_locations:
                                continue
                            _di = item_table.get(_ld.default_item_name)
                            if _di is None or _di.classification != ItemClassification.filler:
                                continue
                            if self._in_location_pool(_ld):
                                continue
                            _reserve.append(_ld.name)
                    self._inject_reserve_names = frozenset(_reserve)
        
        if self.options.enable_dlc:
            # warming stone craft
            item_table["Nomadic Warrior's Cookbook [19]"].classification = ItemClassification.progression
            
            if self.options.dlc_timing != 2:
                item_table["Pureblood Knight's Medal"].classification = ItemClassification.progression
        
        # Promote build-relevant filler to "useful": all weapons, armor, talismans and
        # ashes of war, plus upgrade stones, larval/crystal tears, and spirit ashes among
        # GOODS. Useful items are kept out of missable/excluded locations (default
        # forbid_useful) and may spread in multiworld; this never touches progression.
        _useful_cats = {ERItemCategory.WEAPON, ERItemCategory.ARMOR,
                        ERItemCategory.ACCESSORY, ERItemCategory.ASHOFWAR}
        for _tbl in (item_table, item_table_vanilla):
            for _data in _tbl.values():
                if _data.classification != ItemClassification.filler:
                    continue
                _n = _data.name.lower()
                # Junk ammo (arrows/bolts, er_code 50_000_000..53_599_999) is WEAPON-category
                # but pure filler clutter -- exclude it from the filler->useful gear promotion so
                # it stays filler (dropped in Trimmed/Lean, never spread as a "useful" item that
                # gets sent to players). NOT name-matched: "Bolt of Gransax" is a SPEAR (er_code
                # 16090000, outside this range) and is unaffected. Alaric 2026-06-14: special
                # arrows not worth keeping either -- kill the whole ammo category here.
                if (_data.category == ERItemCategory.WEAPON and _data.er_code is not None
                        and 50_000_000 <= _data.er_code < 53_600_000):
                    continue
                if (_data.category in _useful_cats
                        or "smithing stone" in _n
                        or "larval tear" in _n
                        or "crystal tear" in _n
                        or _n.endswith(" ashes") or "spirit ash" in _n
                        # bigger rune-drop consumables (Golden Rune [13], Numen's, Hero's,
                        # Lord's, Leda's, Marika's, Shadow Realm [2]+). Smaller runes stay filler.
                        or (_data.runes is not None and _data.runes >= 10000)):
                    _data.classification = ItemClassification.useful
                    _data.filler = False  # useful items shouldn't be generated as pad filler
        # Drop anything just demoted from the pad-filler pools.
        filler_item_names[:] = [n for n in filler_item_names
                                if item_table.get(n) is None or item_table[n].filler]
        filler_item_names_vanilla[:] = [n for n in filler_item_names_vanilla
                                if item_table_vanilla.get(n) is None or item_table_vanilla[n].filler]

        # "Fun" consumables (Stonesword Key, Deathroot, Dragon Heart, Starlight Shards,
        # Festering Bloody Finger) are classified progression so they spread
        # meaningfully, but NONE are required to beat the game: they gate optional side content
        # (imp-statue seals, Gurranq's Deathroot rewards, the Caelid Dragon Communion shop, the
        # Seluvis puppets). Under a constrained pool (region_lock + trimmed + DLC-off) that glut
        # of progression has nowhere reachable to land -> priority/progression fill FillError.
        # Demote them to "useful": still real, fun checks, but out of the progression/priority
        # fill. UNCONDITIONAL (Alaric's call: these aren't really progression in any config). The
        # _add_location_rule / _add_entrance_rule asserts are relaxed for them (self._fun_demoted).
        # CAVEAT: under accessibility==full the side-locations they gate must stay reachable -- a
        # starved full pool could fail there, but such configs are already non-viable; minimal is
        # the norm for the constrained pools this targets.
        # EXPERIMENT (2026-06-14): demotion OFF to test whether the restored graveyard
        # locations (29 sphere-1 in Limgrave + ~61 more as regions open) give enough room to
        # keep these as progression. Flip back to `if True:` if the gen can't place them.
        # Re-enabled 2026-06-18, UNCONDITIONAL (Alaric's call: these aren't really
        # progression in any config -- all gate optional side content only, none
        # goal-required). Demoting them keeps the constrained (region_lock + bundle)
        # pool from overflowing the priority/progression fill. NOTE: under
        # accessibility==full the side-locations they gate may become unreachable;
        # run minimal or items if that bites.
        if getattr(self, "_spine_active", False):  # patch_apworld_numregions_dead_progression (B):
            # was `if False` (keep these progression under accessibility=full). Under a spine seal
            # (num_regions / region_count / messmer / godrick -- always accessibility minimal) these
            # optional-side-content goods gate sealed regions -> dead progression that overflows the
            # tiny kept fill. Demote them here ONLY for spine seals; non-spine seeds are unchanged.
            # None are goal-required; all gate only optional side content. Festering Bloody
            # Finger gates nothing in apworld logic (DLC access is Pureblood Knight's Medal --
            # made progression at ~:193 -- not this), so demote it regardless of enable_dlc.
            _fun_prefixes = ["Stonesword Key", "Deathroot", "Dragon Heart", "Starlight Shards",
                             "Festering Bloody Finger", "Seedbed Curse", "Shabriri Grape",
                             # extra optional junk (2026-06-18): none goal-required for
                             # elden_beast; all gate only optional side content. Extend freely.
                             "Imbued Sword Key", "Sewer-Gaol Key", "Giant's Prayerbook",
                             # patch_apworld_numregions_dead_progression: optional-side-gate goods
                             # seen orphaned under num_regions seals (gate only sealed-region
                             # checks: Erudition -> Liurnia Converted Tower; cookbooks -> one
                             # crafting check). Demoted only when progression. Extend freely.
                             "Erudition", "Nomadic Warrior's Cookbook [19]",
                             "Battlefield Priest's Cookbook [4]"]
            # (Seedbed Curse = Dung Eater quest; Shabriri Grape = Frenzied Flame ending -- both
            #  optional for the Elden Beast goal. If goal were frenzied_flame, Shabriri Grape would
            #  matter; revisit the prefix list if a Frenzied-ending goal is ever used.)
            _demoted = 0
            self._fun_demoted = getattr(self, "_fun_demoted", set())
            for _tbl in (item_table, item_table_vanilla):
                for _data in _tbl.values():
                    if (_data.classification == ItemClassification.progression
                            and any(_data.name.startswith(_p) for _p in _fun_prefixes)):
                        _data.classification = ItemClassification.useful
                        _data.filler = False
                        self._fun_demoted.add(_data.name)
                        _demoted += 1
            _lg.error("ER-FUNDEMOTE-DIAG demoted %d fun-consumable items to useful", _demoted)
            try:
                with open(_os.path.join(_os.path.dirname(__file__), "ER_DIAG.txt"), "a") as _df:
                    _df.write("demoted %d fun-consumable items to useful\n" % _demoted)
            except Exception:
                pass

        # Random starting region (SPEC-random-starting-region.md): roll a region to be the free
        # sphere-1 hub instead of Limgrave. Pre-collect its lock (so it joins sphere 1 under the
        # Limgrave-rooted warp graph) and force region_access=warp -- a geographically-deep start has
        # no zero-item physical route, so geographic access would softlock. Lock-based world_logic
        # only; off under dlc_only (Gravesite is already the fixed DLC hub) and under any spine seal
        # (capital/region_count/messmer/godrick reshape the kept set -- defer that combo).
        self._random_start_region = None
        # Roundtable-hub re-root (SPEC-random-start-roundtable-hub.md): Limgrave Lock is a real region
        # lock but only LIVE under random_start -- default it out of the pool so ordinary region_lock
        # seeds don't carry a progression item that gates nothing. Re-enabled below when a start rolls.
        if "Limgrave Lock" in item_table:
            item_table["Limgrave Lock"].inject = False
        # num_regions pool-mode Roundtable re-root (SPEC-num-regions-pool-runes.md): the line above
        # just reset _random_start_region = None and Limgrave Lock inject = False. When num_regions
        # rune-source == pool we WANT the Roundtable-hub re-root (Limgrave is a normal locked region
        # reached by 'Warp To Limgrave'). Set the flag the re-root keys on (_random_start_region) to
        # the always-open hub region and inject Limgrave Lock. _region_lock_warp_access / create_regions
        # / the start-grace block all treat _random_start_region purely as a truthy re-root flag plus a
        # REGION_GRACE_POINTS lookup that harmlessly returns [] for "Roundtable Hold". The standard
        # random_start_region block below is skipped (its YAML option is 0 on num_regions seeds).
        if getattr(self, "_num_regions_pool_reroot", False):
            # num_regions_chain: SPAWN in the chain's link-0 region (a randomly-rolled overworld
            # region whose lock pre_fill precollects) rather than at the Roundtable hub. Roundtable
            # stays the logic root / services hub / KICK fallback (the re-root keys on the flag being
            # truthy, not its value). Resolve link 0 via SPINE (canonical region name); require it be
            # grace-mapped so the start-grace bundle + WarpPlayer target resolve. Fall back to the
            # Roundtable spawn when chain is off or link 0 isn't grace-mapped. SPEC + HANDOFF-num-regions-random-start.md.
            _ns_start = "Roundtable Hold"
            _chain_ord = getattr(self, "_num_regions_chain_order", None)
            if getattr(self, "_num_regions_chain", False) and _chain_ord:
                _step0 = _chain_ord[0]
                if 1 <= _step0 <= len(region_spine.SPINE):
                    _cand = region_spine.SPINE[_step0 - 1].get("name")
                    if _cand in REGION_GRACE_POINTS:
                        _ns_start = _cand
            self._random_start_region = _ns_start
            # Inject Limgrave Lock ONLY when Limgrave is actually KEPT this seed. Under
            # num_regions_chain Limgrave is excluded from the roll (no chain slot) -> sealed, and a
            # sealed Limgrave must not get a loose lock (that was the off-chain 2nd start lock).
            if "Limgrave Lock" in item_table:
                item_table["Limgrave Lock"].inject = (
                    "Limgrave" not in getattr(self, "_spine_sealed_regions", set()))
        _rsr_opt = self.options.random_start_region.value
        if _rsr_opt and self.options.world_logic.value in (0, 2) and not self.options.dlc_only:
            if getattr(self, "_spine_active", False):
                warning(f"{self.player_name}: random_start_region is set but a region-seal goal "
                        f"(capital/num_regions/messmer/godrick) is active; ignoring it for now.")
            else:
                _OVERWORLD_START = ["Weeping Peninsula", "Liurnia of The Lakes", "Caelid", "Altus Plateau"]
                _cands = list(_OVERWORLD_START) if _rsr_opt == 1 else list(REGION_LOCK_ITEM.keys())
                _cands = [r for r in _cands
                          if r in REGION_LOCK_ITEM and r in REGION_GRACE_POINTS
                          and REGION_LOCK_ITEM[r] in item_table
                          and getattr(item_table[REGION_LOCK_ITEM[r]], "inject", False)]
                if _cands:
                    _choice = self.random.choice(sorted(_cands))
                    self._random_start_region = _choice
                    # Roundtable-hub re-root: Limgrave is no longer the free hub -- inject its lock so
                    # it joins the pool like any region (hub moves to Roundtable in create_regions /
                    # _region_lock_warp_access). SPEC-random-start-roundtable-hub.md.
                    if "Limgrave Lock" in item_table:
                        item_table["Limgrave Lock"].inject = True
                    _lock = REGION_LOCK_ITEM[_choice]
                    item_table[_lock].inject = False
                    self.multiworld.push_precollected(self.create_item(_lock))
                    if self.options.region_access.value != 1:
                        self.options.region_access.value = 1
                        warning(f"{self.player_name}: random_start_region forces region_access=warp "
                                f"(geographic access from a deep start can softlock).")
                else:
                    warning(f"{self.player_name}: random_start_region found no legal start region "
                            f"under these settings; starting in Limgrave (vanilla).")
        exclude_local_item_only_lowercase = [key.lower() for key in self.options.exclude_local_item_only.value]
        using_table = item_table_vanilla
        if self.options.enable_dlc: using_table = item_table
        for item in using_table.values(): # loop of whole item table
            if self.options.local_item_option:
                if item.classification != ItemClassification.progression and item.classification != ItemClassification.useful:
                    match item.category: # this works, could be better
                        case ERItemCategory.GOODS:
                            if 'goods' not in exclude_local_item_only_lowercase:
                                self.options.local_items.value.add(item.name)
                            break
                        case ERItemCategory.WEAPON:
                            if 'weapon' not in exclude_local_item_only_lowercase:
                                self.options.local_items.value.add(item.name)
                            break
                        case ERItemCategory.ARMOR:
                            if 'armor' not in exclude_local_item_only_lowercase:
                                self.options.local_items.value.add(item.name)
                            break
                        case ERItemCategory.ACCESSORY:
                            if 'accessory' not in exclude_local_item_only_lowercase:
                                self.options.local_items.value.add(item.name)
                            break
                        case ERItemCategory.ASHOFWAR:
                            if 'ashofwar' not in exclude_local_item_only_lowercase:
                                self.options.local_items.value.add(item.name)
                            break

    def create_regions(self) -> None: #MARK: Connections
        # Create Vanilla Regions
        regions: Dict[str, Region] = {"Menu": self.create_region("Menu", {})}
        regions.update({region_name: self.create_region(region_name, location_tables[region_name]) for region_name in region_order})

        # Create DLC Regions
        if self.options.enable_dlc:
            regions.update({region_name: self.create_region(region_name, location_tables[region_name]) for region_name in region_order_dlc})

        # Connect Regions
        def create_connection(from_region: str, to_region: str):
            connection = Entrance(self.player, f"Go To {to_region}", regions[from_region])
            regions[from_region].exits.append(connection)
            connection.connect(regions[to_region])

        regions["Menu"].exits.append(Entrance(self.player, "New Game", regions["Menu"]))
        # Roundtable-hub re-root (SPEC-random-start-roundtable-hub.md): under random_start the
        # hub/logic-root is Roundtable Hold (always-open interior), not Limgrave; Limgrave is reached
        # via a lock-gated Warp To Limgrave (see _region_lock_warp_access). Normal seeds: unchanged.
        _ng_root = "Roundtable Hold" if getattr(self, "_random_start_region", None) else "Limgrave"
        self.multiworld.get_entrance("New Game", self.player).connect(regions[_ng_root])
        
